def binary_search(catalog, title):
    low = 0
    high = len(catalog) - 1
    while low <= high:
        mid = (low + high) // 2
        guess = catalog[mid]
        if guess == title:
            return mid
        if guess > title:
            high = mid - 1
        else:
            low = mid + 1
    return -1

